**Search 函数实现：**

```cpp
template <class elemType>
int seqList< elemType >:: search(const elemType &x) const {
    int i;
    for (i = 0; i < currentLength; i++) {
        if (data[i] == x) {
            break;
        }
    }
    if (i == currentLength) {
        return -1;
    } else {
        return i;
    }
}
