InToSufForm

void inToSufForm(char *inStr, char *sufStr)
char topCh, hash = '#';
s.push(hash);
i = 0; j = 0;
while (inStr[i] != '\0')
if ((inStr[i] >= '0') && (inStr[i] <= '9'))
sufStr[j++] = inStr[i++];
switch (inStr[i])
case '(': s.push(inStr[i]); break;
case ')':
topCh = s.pop();
while (topCh != '(')
sufStr[j++] = topCh; topCh = s.pop();
break;
case '*': case '/':
topCh = s.top();
while ((topCh == '*') || (topCh == '/'))
s.pop();
sufStr[j++] = topCh; topCh = s.top();
s.push(inStr[i]);
break;

