template <class elemType>
int BTree<elemType>:: Size()
{
    return Size(root);
}

template <class elemType>
int BTree<elemType>:: Size (Node *t)
{
    if (!t) return 0;
    return 1 + Size(t->left) + Size(t->right);
}
