if (!root) return;
Node *p;
seqStack<Node *> s1;
seqStack<int> s2;
int zero = 0, one = 1, two = 2;
int flag;

s1.push(root);
s2.push(zero);

while (!s1.isEmpty()) {
    flag = s2.top(); s2.pop();
    p = s1.top();
    switch(flag) {
        case 2:
            s1.pop();
            cout << p->data;
            break;
        case 1:
            s2.push(two);
            if (p->right) {
                s1.push(p->right);
                s2.push(zero);
                break;
            }
        case 0:
            s2.push(one);
            if (p->left) {
                s1.push(p->left);
                s2.push(zero);
                break;
            }
    }
}
